import{_ as i,o as e,c as t,a2 as a}from"./chunks/framework.CZqXuAiL.js";const c=JSON.parse('{"title":"Metrics API","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/user-guide/metrics-api.md","filePath":"openshield-xdp/user-guide/metrics-api.md","lastUpdated":1785906636000}'),n={name:"openshield-xdp/user-guide/metrics-api.md"};function l(o,s,h,d,p,r){return e(),t("div",null,[...s[0]||(s[0]=[a(`<h1 id="metrics-api" tabindex="-1">Metrics API <a class="header-anchor" href="#metrics-api" aria-label="Permalink to &quot;Metrics API&quot;">​</a></h1><p>Since v2.0, OpenShield-XDP can serve <strong>everything the TUI shows</strong> as plain JSON over HTTP — traffic, mitigation, attack state, bans, top offenders/ports, behavior clusters, attack history, and the active mitigation config (secrets stripped). Use it to feed Grafana, a status page, or your own tooling. There is no Prometheus dependency; you just poll an endpoint.</p><p><strong>It is disabled by default.</strong></p><h2 id="enabling" tabindex="-1">Enabling <a class="header-anchor" href="#enabling" aria-label="Permalink to &quot;Enabling&quot;">​</a></h2><p>In <code>/etc/openshield/openshield.yaml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">metrics</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  listen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1:9100&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # local only; use 0.0.0.0:9100 for remote dashboards</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  api_key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;osk_...&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # pre-generated randomly per install</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  rate_limit_per_sec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # per source IP; 0 = unlimited</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  whitelist</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># IP/CIDR allowlist; empty = any IP (key still required)</span></span></code></pre></div><p>Key, rate-limit and listen-address changes apply <strong>without a restart</strong> (<code>sudo openshield reload</code>). Changing <code>whitelist</code> requires a loader restart (<code>sudo openshield unload &amp;&amp; sudo openshield load</code>).</p><h2 id="getting-your-url-and-key" tabindex="-1">Getting your URL and key <a class="header-anchor" href="#getting-your-url-and-key" aria-label="Permalink to &quot;Getting your URL and key&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key</span></span></code></pre></div><p>Prints the endpoint URL, health path, your API key, and a ready-to-paste <code>curl</code> example — but only when the endpoint is enabled; otherwise it tells you how to enable it.</p><p>Managing the key (both are hot-applied, no restart):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-ke</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # bring your own key (min 8 chars)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> regen</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # rotate to a fresh random key</span></span></code></pre></div><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Method</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>/metrics</code></td><td>GET</td><td>yes</td><td>Full JSON snapshot (schema below)</td></tr><tr><td><code>/health</code></td><td>GET</td><td>yes</td><td><code>{ &quot;status&quot;: &quot;ok&quot;, &quot;generated_at&quot;: &lt;unix&gt; }</code></td></tr></tbody></table><p>Send the key as a Bearer token (or <code>?key=</code> query parameter):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer osk_1a2b3c...&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:9100/metrics</span></span></code></pre></div><h3 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td>401</td><td>Missing/invalid API key</td></tr><tr><td>403</td><td>Source IP not in <code>metrics.whitelist</code></td></tr><tr><td>429</td><td>Rate limit exceeded</td></tr><tr><td>405</td><td>Non-GET method</td></tr></tbody></table><p>All errors are JSON: <code>{ &quot;error&quot;: &quot;...&quot; }</code>.</p><h2 id="response-shape-metrics" tabindex="-1">Response shape (<code>/metrics</code>) <a class="header-anchor" href="#response-shape-metrics" aria-label="Permalink to &quot;Response shape (\`/metrics\`)&quot;">​</a></h2><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;generated_at&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1754325123</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;snapshot&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:  { </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// the full TUI dashboard snapshot</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;behavior&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:  { </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// behavior engine state + clusters</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;attacks&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:   [ </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ],  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// last 50 attack records</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;config&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:    { </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// active mitigation config, secrets stripped</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Highlights of what&#39;s inside:</p><ul><li><strong><code>snapshot.global</code></strong> — <code>current_pps</code>, <code>current_bps</code>, <code>passed_pps</code>, drop/pass rates, totals. The <code>current_pps</code> vs <code>passed_pps</code> pair is your proof-of-mitigation: what&#39;s arriving vs what got through.</li><li><strong><code>snapshot.traffic</code></strong> — per-protocol rates, peaks, <code>top_ports</code>, and per-second history series (<code>pps_history</code>, <code>bps_history</code>, <code>drop_rate_history</code>, newest last — graph them directly).</li><li><strong><code>snapshot.attack</code></strong> — <code>state</code> (<code>NORMAL</code>/<code>UNDER_ATTACK</code>), type, duration, baseline + spike thresholds, packets dropped, IPs banned, new sources blocked.</li><li><strong><code>snapshot.bans</code> / <code>snapshot.top_offenders</code></strong> — active ban count and recent entries (IP, reason, expiry, star level); per-IP rates and suspicion scores.</li><li><strong><code>behavior</code></strong> — <code>enabled</code>, <code>auto_block</code>, live clusters (<code>state</code>, <code>confidence</code>, <code>reasons</code> like &quot;machine-paced timing&quot;), and learned per-port baselines.</li><li><strong><code>attacks</code></strong> — up to 50 recent attack records: peak/avg/p95 pps, IPs involved, protocol mix, <code>forensics_dir</code>.</li><li><strong><code>config</code></strong> — flat <code>key = value</code> map of the active mitigation config. License keys, webhook URLs and other secrets are excluded by construction.</li></ul><h2 id="integration-notes" tabindex="-1">Integration notes <a class="header-anchor" href="#integration-notes" aria-label="Permalink to &quot;Integration notes&quot;">​</a></h2><ul><li>Poll every 1–5 s. The payload is a cached snapshot refreshed at the telemetry poll interval (default 1 s) — polling faster just burns rate-limit tokens.</li><li>The config file (and thus the key) is stored <code>0600</code>, root-only.</li><li>Binding remotely? Keep <code>listen</code> on localhost unless you need it, and set <code>whitelist</code> to your dashboard host&#39;s IP when listening on all interfaces:</li></ul><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">metrics</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  listen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.0.0.0:9100&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  whitelist</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;198.51.100.20&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>Rotate the key if it ever leaks: <code>sudo openshield key regen</code>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p><a href="/pingless-studios-docs/openshield-xdp/user-guide/config-values">Config Values in Plain Language</a> · <a href="/pingless-studios-docs/openshield-xdp/user-guide/cli">CLI Reference</a> · <a href="/pingless-studios-docs/openshield-xdp/user-guide/tui">TUI Guide</a></p>`,29)])])}const g=i(n,[["render",l]]);export{c as __pageData,g as default};
